fn frame(t: i32) {
    host::display::clear(0x000000);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2 + 30;
    let r: i32 = 120;
    let mut i: i32 = 0;
    while i <= 20 {
        let a: i32 = 112 + i * 8;
        let inner: i32 = if (i % 5) == 0 { r - 16 } else { r - 8 };
        let x0: i32 = cx + (inner * host::math::cos(a)) / 256;
        let y0: i32 = cy + (inner * host::math::sin(a)) / 256;
        let x1: i32 = cx + (r * host::math::cos(a)) / 256;
        let y1: i32 = cy + (r * host::math::sin(a)) / 256;
        let col: i32 = if i >= 17 { 0xff3333 } else { 0x999999 };
        host::display::draw_line(x0, y0, x1, y1, col);
        i = i + 1;
    }
    let v: i32 = 50 + (host::math::sin(t) * 50) / 256;
    let na: i32 = 112 + (v * 160) / 100;
    let nx: i32 = cx + ((r - 24) * host::math::cos(na)) / 256;
    let ny: i32 = cy + ((r - 24) * host::math::sin(na)) / 256;
    host::display::draw_line(cx, cy, nx, ny, 0xffffff);
    host::display::fill_rect(cx - 3, cy - 3, 7, 7, 0xffffff);
    host::display::draw_number(cx - 16, cy + 24, v, 0xffffff, 2);
    host::display::present();
}
